class OnlineConvolutiveICA:
    def __init__(self, n_mics=6, n_sources=2, frame=512, hop=256):
        self.n_mics = n_mics
        self.n_sources = n_sources
        self.frame = frame
        self.hop = hop
        self._init_whitening()
        self._init_demixers()
        self.bin_clusters = []

    def _init_whitening(self):
        self.whitener = ZCAWhitener()

    def _init_demixers(self):
        self.W = {
            b: np.eye(self.n_mics, self.n_sources) * 0.99
            for b in range(self.frame // 2 + 1)
        }

    def process_frame(self, x_frame):
        X = self.stft(x_frame)
        Y = self._demix_binwise(X)
        self._align_permutations(Y)
        self._update_adaptive(Y)
        return self.istft(Y)

    def _demix_binwise(self, X):
        Y = {}
        for b, W in self.W.items():
            Y[b] = W.conj().T @ X[b]
        return Y

    def _align_permutations(self, Y):
        clusters = bin_correlation_clustering(Y)
        self.bin_clusters = merge_with_temporal continuity(clusters)

    def _update_adaptive(self, Y, update_period_ms=5):
        if self._should_update():
            for b, W in self.W.items():
                g = natural_gradient(Y[b])
                self.W[b] = update(W, g, step=self.step_size)

    def _should_update(self):
        return self.frame_count % self.update_every == 0
